import json,collections,html,hashlib
from pathlib import Path
root=Path(__file__).resolve().parents[1];folder=root/'data/validation/llm-drawing-review-2026-09-22'
read=lambda name:json.loads((folder/name).read_text(encoding='utf-8'))
manifest=read('manifest.json');numeric=read('numeric-summary.json');reviews=[read('vision-review-a.json'),read('vision-review-b.json')]
cases=[c for r in reviews for c in r['cases']];byid={c['caseId']:c for c in cases};ids={c['id'] for c in manifest['cases']}
if len(cases)!=24 or set(byid)!=ids:raise RuntimeError('Visual review coverage incomplete or duplicate')
input_hashes=read('review-input-hashes.json')
if set(input_hashes)!=ids or any(hashlib.sha256((folder/'sheets'/f'{i}.png').read_bytes()).hexdigest()!=input_hashes[i] for i in ids):raise RuntimeError('Review sheet changed; repeat visual review before publishing verdicts')
counts=dict(collections.Counter(c['verdict'] for c in cases));severity=dict(collections.Counter(f['severity'] for c in cases for f in c['findings']))
failed=[c['caseId'] for c in cases if c['verdict']=='fail']
summary={'version':'HEADUP-LLM-DRAWING-REVIEW-1','cases':24,'freshDownloads':8,'verifiedCachedProfiles':16,'numeric':numeric,'visual':{'counts':counts,'findingSeverities':severity,'flaggedCases':failed,'meaning':'model visual triage, not ground-truth accuracy'},'reviewers':'Two current Codex vision agents in separate review contexts; no separate cloud-provider API','limitations':['Consented adults; no child/longitudinal validation','Development/research regression set, not independent holdout','Visual pass does not prove precise anatomy; some regions remain unclear']}
(folder/'summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2),encoding='utf-8')
labels={'pass':'未见重大错位','fail':'需修正/人工核验','unassessable':'无法判断'};views={'front':'正面','left_profile':'左侧','right_profile':'右侧'}
lines=['# 自动图片测试与大模型绘制复核','', '**结论：数值计算自洽，侧面关键点定位仍有明显待核验问题。**','',f"- 24张：8组正面/左右侧。8张通过作者镜像新下载，16张为SHA-256验证的官方缓存；Figshare原下载端返回403。",f"- {numeric['availableReadings']}项可用读数全部完成独立点线复算：{numeric['audit'].get('pass',0)}通过，{len(numeric['numericFailures'])}不一致。112个未输出项目不记为通过。",f"- 大模型实际逐张查看全部24张：{counts.get('pass',0)}张未见明确重大错位，{counts.get('fail',0)}张标记需修正/人工核验。通过病例仍可能包含轻微疑点或不可观察区域。",'- 复核由本次Codex视觉模型的两个审查上下文完成，未调用其他供应商的视觉API。模型判断未预先读取自动复算结果。','', '[打开全部24张四联图与逐图意见](gallery.html)','', '## 主要发现','', '1. 部分侧面眉点/眉线偏在可见眉毛上方，属于定位问题。','2. 013、017的左右侧被标记下颌中后段偏入面颊。部分区域边界弱，仍需专业人工标注确认。','3. 未发现此前眼部点串到唇部的拓扑错误或整体左右翻转。','4. 24张均通过现有拍摄门槛，但门槛通过并不能保证每个关键点准确。','', '## 被标记的7张照片','', '| 样本 | 可见问题 | 证据 |','|---|---|---|']
for c in cases:
 if c['verdict']=='fail':
  descriptions='；'.join(f['visibleEvidence'] for f in c['findings'] if f['severity'] in ['major','blocker'])
  lines.append('| '+c['caseId']+' | '+descriptions.replace('|','/')+' | [四联图](sheets/'+c['caseId']+'.png) |')
lines+=['','## 结果不能证明什么','', '这批是公开授权的成人研究照片，不是儿童样本，不是跨期复拍，也不是新的独立保留集。大模型肉眼审查不是人工点位真值；296项复算一致只说明显示数值符合保存点线，不能证明点落在准确解剖位置。','', '## 下一步优先项','', '- 为侧面眉部和下颌建立明确的人工标注规则与独立验收集，区分可见皮肤边缘、阴影和不可观察部分。','- 优先改进上述关键点定位及异常输出拦截，避免用平滑或整体偏移让线看似贴合。','- 以获授权的儿童同日重复拍摄验证误差，再设定可识别的跨期变化阈值。','', '## 文件和复现','', '- manifest.json：下载来源、许可证、校验摘要、缓存标识。','- results/：每张完整检测、点线依据和独立复算。','- sheets/：四联图。','- vision-review-a.json / vision-review-b.json：大模型逐图意见。','- numeric-summary.json / summary.json：机器可读汇总。','- REVIEW-RUBRIC.md：视觉审查规则。','', '运行 scripts/download-drawing-review.py 下载/校验，node scripts/serve-drawing-review.mjs 启动本机批量页面，点击运行；随后 node --experimental-strip-types scripts/audit-drawing-review.mjs 独立复算。按审查规则让Codex逐张看图写入视觉JSON后，运行 scripts/build-drawing-review-report.py 生成报告。','', '来源：[Face Research Lab London Set](https://figshare.com/articles/dataset/Face_Research_Lab_London_Set/5047666/5)，Lisa DeBruine、Benedict Jones，CC BY 4.0；作者镜像：[webmorphR.stim](https://github.com/debruine/webmorphR.stim)。仅作本机研究验证，不包含用户照片，不打包进APP。']
(folder/'REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
esc=html.escape
cards=[]
for item in manifest['cases']:
 c=byid[item['id']];findings=''.join('<li><b>'+esc(f['severity'])+' · '+esc(f.get('region',''))+'</b> '+esc(f['visibleEvidence'])+'<small>'+esc(f.get('action',''))+'</small></li>' for f in c['findings']) or '<li>未见明确重大错位；不代表所有点已通过精度验证。</li>'
 unclear='；'.join(c.get('notAssessable',[]))
 cards.append('<article data-verdict="'+c['verdict']+'"><header><h2>'+esc(item['id'])+' · '+views[item['view']]+'</h2><span class="'+c['verdict']+'">'+labels[c['verdict']]+'</span></header><a href="sheets/'+item['id']+'.png" target="_blank"><img loading="lazy" src="sheets/'+item['id']+'.png" alt="'+esc(item['id'])+'四联复核图"></a><ul>'+findings+'</ul>'+('<p class="unclear">无法确认：'+esc(unclear)+'</p>' if unclear else '')+'</article>')
page='<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HeadUp 绘制复核</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f3f0;color:#28252a;font:15px/1.7 system-ui,sans-serif}main{max-width:1280px;margin:auto;padding:28px}h1{font-size:30px;margin:0}p{max-width:1000px}.stats{display:flex;flex-wrap:wrap;gap:12px}.stats div{background:white;padding:16px 22px;border-radius:12px}.stats strong{display:block;font-size:25px}nav{position:sticky;top:0;background:#f5f3f0ed;padding:14px 0;display:flex;flex-wrap:wrap;gap:8px}button{padding:10px 16px;border:1px solid #d8cbd1;background:white;border-radius:8px;cursor:pointer}button[aria-pressed=true]{background:#762d43;color:white}article{background:white;border:1px solid #e3dce0;border-radius:14px;margin:20px 0;overflow:hidden}article header{display:flex;align-items:center;justify-content:space-between;padding:12px 20px;gap:12px}h2{font-size:18px;margin:0}article img{width:100%;display:block}article ul,article p{margin:16px 28px}small{display:block;color:#67616a}span.fail{color:#9b3035}span.pass{color:#367249}.unclear{color:#705c3c}footer{padding:22px 0;color:#67616a}a{color:#762d43}@media(max-width:640px){main{padding:16px}article header{display:block}.stats div{padding:12px}}</style></head><body><main><h1>HeadUp 自动绘制复核</h1><p>24张成人研究照片，分别检查计算一致性与模型视觉定位。数值自洽不等于关键点定位准确。</p><div class="stats"><div><strong>24</strong>实际处理并逐图复核</div><div><strong>296 / 296</strong>可用读数独立复算一致</div><div><strong>17</strong>未见重大错位</div><div><strong>7</strong>需修正或人工核验</div></div><p>新下载8张正面；官方侧面下载受403限制，16张使用已校验缓存。当前Codex视觉模型分别复核两组各12张，未预先读取数值审计。点击图片可放大。</p><nav aria-label="筛选审查结果"><button data-filter="all" aria-pressed="true">全部24张</button><button data-filter="fail" aria-pressed="false">问题7张</button><button data-filter="pass" aria-pressed="false">未见重大错位17张</button></nav>'+''.join(cards)+"<footer>本报告不是临床精度或儿童发育验证。部分软阴影、毛发遮挡区域无法视觉确认。来源：Face Research Lab London Set · Lisa DeBruine / Benedict Jones · CC BY 4.0。仅供本机研究验证。</footer></main><script>document.querySelectorAll('button[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('button[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('article[data-verdict]').forEach(a=>a.hidden=b.dataset.filter!=='all'&&a.dataset.verdict!==b.dataset.filter)}));</script></body></html>"
page=page.replace('<strong>17</strong>','<strong>'+str(counts.get('pass',0))+'</strong>').replace('<strong>7</strong>','<strong>'+str(counts.get('fail',0))+'</strong>').replace('问题7张','问题'+str(counts.get('fail',0))+'张').replace('未见重大错位17张','未见重大错位'+str(counts.get('pass',0))+'张')
(folder/'gallery.html').write_text(page,encoding='utf-8')
print(json.dumps({'cases':len(cases),'visual':counts,'findings':severity,'numericPass':numeric['audit']['pass'],'flagged':failed},ensure_ascii=True))
